-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE events(id INTEGER, day INTEGER);
-- INSERT INTO events VALUES(1,2),(2,3),(3,5);
-- CREATE TABLE periods(id INTEGER, start_day INTEGER, end_day INTEGER);
-- INSERT INTO periods VALUES(1,1,3),(2,3,5);
SELECT COUNT(*) FROM events AS e
JOIN periods AS p
  ON e.day >= p.start_day AND e.day < p.end_day;
